/**
 * Default dispatch decisions for the Bitbucket channel: turn auth derived
 * from the delivery's actor, the title / message a turn starts with, and
 * which pull-request events dispatch when no `onPullRequest` hook exists.
 */
import { BitbucketApiBaseMissingError } from "./api-base-missing.js";
import { BitbucketCredentialMissingError, } from "./api.js";
import { bitbucketRepositoryFromState, buildBitbucketBinding, formatBitbucketOutboundComment, } from "./binding.js";
function issuerHost(ctx) {
    if (ctx.repository.htmlUrl !== undefined) {
        try {
            return new URL(ctx.repository.htmlUrl).host;
        }
        catch {
            // fall through to the dialect default
        }
    }
    return ctx.repository.dialect === "cloud" ? "bitbucket.org" : "bitbucket-data-center";
}
/**
 * Derive the turn's auth from the actor that triggered the delivery — the
 * standard `{ auth: defaultBitbucketAuth(ctx) }` dispatch from an inbound
 * hook. The subscriber's Cursor identity is not the turn principal (same
 * pattern as `defaultGitHubAuth` / `defaultGitLabAuth`).
 */
export function defaultBitbucketAuth(ctx) {
    const sender = ctx.sender;
    return {
        authenticator: "bitbucket-webhook",
        principalId: sender === undefined ? "bitbucket" : sender.id,
        principalType: "user",
        attributes: {
            conversation_kind: ctx.pullRequestId === undefined ? ctx.eventType : "pull_request",
            repo: ctx.repository.fullName,
            dialect: ctx.repository.dialect,
            ...(ctx.deliveryId === undefined ? {} : { delivery_id: ctx.deliveryId }),
            ...(sender === undefined
                ? {}
                : {
                    subject: sender.id,
                    ...(sender.username === undefined ? {} : { username: sender.username }),
                }),
            issuer: `bitbucket:${issuerHost(ctx)}`,
        },
    };
}
export function defaultBitbucketTitle(ctx) {
    return ctx.pullRequestId === undefined
        ? `Bitbucket ${ctx.repository.fullName} ${ctx.eventType}`
        : `Bitbucket ${ctx.repository.fullName}#${ctx.pullRequestId}`;
}
export function defaultBitbucketPullRequestMessage(ctx, pullRequest) {
    const head = pullRequest.sourceBranch !== undefined && pullRequest.headSha !== undefined
        ? `Head: ${pullRequest.sourceBranch} (${pullRequest.headSha})`
        : undefined;
    return [
        `Bitbucket pull request trigger: ${ctx.repository.fullName}#${pullRequest.id}`,
        `Action: ${pullRequest.action}`,
        ...(pullRequest.htmlUrl === undefined ? [] : [`URL: ${pullRequest.htmlUrl}`]),
        ...(pullRequest.title === undefined ? [] : [`Title: ${pullRequest.title}`]),
        ...(head === undefined ? [] : [head]),
        "Handle this pull request event.",
    ].join("\n");
}
/**
 * Dispatch from the payload alone: a new pull request, or an `updated`
 * whose `previousHeadSha` differs from the head. The channel also remembers
 * the last head and draft when no hook is set.
 */
export function defaultBitbucketPullRequestDispatch(ctx, pullRequest) {
    const dispatches = pullRequest.action === "created" ||
        (pullRequest.action === "updated" &&
            pullRequest.previousHeadSha !== undefined &&
            pullRequest.previousHeadSha !== pullRequest.headSha);
    if (!dispatches) {
        return null;
    }
    return { auth: defaultBitbucketAuth(ctx) };
}
const BITBUCKET_FAILURE_COMMENT = [
    "I hit an error while handling your request.",
    "",
    "Please try again, or reach out if it keeps failing.",
].join("\n");
/**
 * Built-in delivery: post assistant text on `message.completed`, and a short
 * error comment on `turn.failed` or `session.failed`. A task-mode failure
 * emits both for the same turn, so `session.failed` stays quiet when
 * `turn.failed` already posted for that turn; a `session.failed` with no
 * preceding `turn.failed` still posts. Both go through the same binding as
 * `ctx.bitbucket` (proxy when the host bound one, otherwise the token). A
 * reply is skipped, not failed, when no credential or API base is configured.
 */
export function buildDefaultBitbucketEvents(options = {}) {
    if (options.deliverReplies === false) {
        return {};
    }
    // Latest turn that already posted a failure comment, per session.
    const failedTurnBySession = new Map();
    return {
        async "turn.started"(event) {
            failedTurnBySession.delete(event.sessionId);
        },
        async "session.waiting"(event) {
            failedTurnBySession.delete(event.sessionId);
        },
        async "session.completed"(event) {
            failedTurnBySession.delete(event.sessionId);
        },
        async "message.completed"(event, channel) {
            if (event.data.parentCallId !== undefined ||
                event.data.finishReason === "tool_call" ||
                event.data.text === "") {
                return;
            }
            await postBitbucketReply(channel.state, options, event.data.text);
        },
        async "turn.failed"(event, channel) {
            const posted = await postBitbucketReply(channel.state, options, BITBUCKET_FAILURE_COMMENT);
            if (posted) {
                failedTurnBySession.set(event.sessionId, event.turnId);
            }
        },
        async "session.failed"(event, channel) {
            const alreadyPosted = failedTurnBySession.has(event.sessionId) &&
                failedTurnBySession.get(event.sessionId) === event.turnId;
            failedTurnBySession.delete(event.sessionId);
            if (alreadyPosted) {
                return;
            }
            await postBitbucketReply(channel.state, options, BITBUCKET_FAILURE_COMMENT);
        },
    };
}
async function postBitbucketReply(state, options, body) {
    const repository = bitbucketRepositoryFromState(state);
    if (repository === undefined || state.pullRequestId === null) {
        return false;
    }
    try {
        const handle = buildBitbucketBinding({
            repository,
            proxy: options.proxy?.(),
            token: options.token,
            apiBaseUrl: options.apiBaseUrl,
        });
        await handle.api.postPullRequestComment(state.pullRequestId, {
            body: formatBitbucketOutboundComment(body),
        });
        return true;
    }
    catch (error) {
        if (error instanceof BitbucketApiBaseMissingError) {
            console.warn(`[sdk] bitbucket reply skipped for ${repository.fullName}#${String(state.pullRequestId)}: ${error.message}`);
            return false;
        }
        if (error instanceof BitbucketCredentialMissingError) {
            return false;
        }
        throw error;
    }
}
